class Solution:
    def smallestString(self, s: str) -> str:
        n = len(s)
        def cons(a, b):
            d = abs(ord(a) - ord(b))
            return d == 1 or d == 25
        dele = [[False] * n for _ in range(n)]
        for L in range(2, n + 1):
            for i in range(n - L + 1):
                j = i + L - 1
                if cons(s[i], s[j]) and (L == 2 or dele[i + 1][j - 1]):
                    dele[i][j] = True
                    continue
                for k in range(i, j):
                    if dele[i][k] and dele[k + 1][j]:
                        dele[i][j] = True
                        break
        memo = [[None] * n for _ in range(n)]
        def f(i, j):
            if i > j:
                return ""
            if memo[i][j] is not None:
                return memo[i][j]
            if dele[i][j]:
                memo[i][j] = ""
                return ""
            r = s[i] + f(i + 1, j)
            for k in range(i, j):
                c = f(i, k) + f(k + 1, j)
                if c < r:
                    r = c
            for p in range(i + 1, j + 1):
                if cons(s[i], s[p]) and (p == i + 1 or dele[i + 1][p - 1]):
                    c = f(p + 1, j)
                    if c < r:
                        r = c
            memo[i][j] = r
            return r
        return f(0, n - 1)

