class Solution {
public:
    string smallestString(string s) {
        int n = s.size();
        auto cons = [&](int i, int j) {
            int d = abs(s[i] - s[j]);
            return d == 1 || d == 25;
        };
        vector<vector<char>> del(n, vector<char>(n, 0));
        for (int L = 2; L <= n; L++)
            for (int i = 0; i + L <= n; i++) {
                int j = i + L - 1;
                if (cons(i, j) && (L == 2 || del[i + 1][j - 1])) { del[i][j] = 1; continue; }
                for (int k = i; k < j; k++)
                    if (del[i][k] && del[k + 1][j]) { del[i][j] = 1; break; }
            }
        vector<vector<string>> memo(n, vector<string>(n));
        vector<vector<char>> vis(n, vector<char>(n, 0));
        function<string(int,int)> f = [&](int i, int j) -> string {
            if (i > j) return "";
            if (vis[i][j]) return memo[i][j];
            vis[i][j] = 1;
            if (del[i][j]) return memo[i][j] = "";
            string r = s.substr(i, 1) + f(i + 1, j);
            for (int k = i; k < j; k++) {
                string c = f(i, k) + f(k + 1, j);
                if (c < r) r = c;
            }
            for (int p = i + 1; p <= j; p++)
                if (cons(i, p) && (p == i + 1 || del[i + 1][p - 1])) {
                    string c = f(p + 1, j);
                    if (c < r) r = c;
                }
            return memo[i][j] = r;
        };
        return f(0, n - 1);
    }
};

