class Solution {
    private String s;
    private boolean[][] del, vis;
    private String[][] memo;
    private boolean cons(int i, int j) {
        int d = Math.abs(s.charAt(i) - s.charAt(j));
        return d == 1 || d == 25;
    }
    public String smallestString(String s) {
        this.s = s;
        int n = s.length();
        del = new boolean[n][n]; vis = new boolean[n][n]; memo = new String[n][n];
        for (int L = 2; L <= n; L++)
            for (int i = 0; i + L <= n; i++) {
                int j = i + L - 1;
                if (cons(i, j) && (L == 2 || del[i + 1][j - 1])) { del[i][j] = true; continue; }
                for (int k = i; k < j; k++)
                    if (del[i][k] && del[k + 1][j]) { del[i][j] = true; break; }
            }
        return f(0, n - 1);
    }
    private String f(int i, int j) {
        if (i > j) return "";
        if (vis[i][j]) return memo[i][j];
        vis[i][j] = true;
        if (del[i][j]) return memo[i][j] = "";
        String r = s.charAt(i) + f(i + 1, j);
        for (int k = i; k < j; k++) {
            String c = f(i, k) + f(k + 1, j);
            if (c.compareTo(r) < 0) r = c;
        }
        for (int p = i + 1; p <= j; p++)
            if (cons(i, p) && (p == i + 1 || del[i + 1][p - 1])) {
                String c = f(p + 1, j);
                if (c.compareTo(r) < 0) r = c;
            }
        return memo[i][j] = r;
    }
}

