var smallestString = function(s) {
    const n = s.length;
    const cons = (i, j) => {
        const d = Math.abs(s.charCodeAt(i) - s.charCodeAt(j));
        return d === 1 || d === 25;
    };
    const del = Array.from({length: n}, () => new Array(n).fill(false));
    for (let L = 2; L <= n; L++)
        for (let i = 0; i + L <= n; i++) {
            const j = i + L - 1;
            if (cons(i, j) && (L === 2 || del[i + 1][j - 1])) { del[i][j] = true; continue; }
            for (let k = i; k < j; k++)
                if (del[i][k] && del[k + 1][j]) { del[i][j] = true; break; }
        }
    const memo = Array.from({length: n}, () => new Array(n).fill(null));
    const f = (i, j) => {
        if (i > j) return '';
        if (memo[i][j] !== null) return memo[i][j];
        if (del[i][j]) return memo[i][j] = '';
        let r = s[i] + f(i + 1, j);
        for (let k = i; k < j; k++) {
            const c = f(i, k) + f(k + 1, j);
            if (c < r) r = c;
        }
        for (let p = i + 1; p <= j; p++)
            if (cons(i, p) && (p === i + 1 || del[i + 1][p - 1])) {
                const c = f(p + 1, j);
                if (c < r) r = c;
            }
        return memo[i][j] = r;
    };
    return f(0, n - 1);
};
